      at(0).then((ended) => {
        lifetime.finish!(
          layer.secondary.length
            ? { ...ended, teardownErrors: [...(ended.teardownErrors ?? []), ...layer.secondary] }
            : ended,
        );
        layer.secondary.length = 0;
